SELECT COALESCE(SUM(normalCount), 0) AS normalDeviceNum, COALESCE(SUM(abnormalCount), 0) AS abnormalDeviceNum FROM (
SELECT COUNT(CASE WHEN monitor_status IN ('1', '正常') THEN 1 END) AS normalCount, COUNT(CASE WHEN monitor_status NOT IN ('1', '正常') THEN 1 END) AS abnormalCount FROM space_monitor WHERE deleted = 0
AND station_id = #{stationId}
AND create_time BETWEEN #{statTimeStart} AND #{statTimeEnd}
UNION ALL
SELECT COUNT(CASE WHEN monitor_status IN ('0', '正常') THEN 1 END) AS normalCount, COUNT(CASE WHEN monitor_status NOT IN ('0', '正常') THEN 1 END) AS abnormalCount FROM car_charge_monitor WHERE deleted = 0
AND station_id = #{stationId}
AND create_time BETWEEN #{statTimeStart} AND #{statTimeEnd}
UNION ALL
SELECT COUNT(CASE WHEN monitor_status IN ('0', '正常') THEN 1 END) AS normalCount, COUNT(CASE WHEN monitor_status NOT IN ('0', '正常') THEN 1 END) AS abnormalCount FROM bike_charge_monitor WHERE deleted = 0
AND station_id = #{stationId}
AND create_time BETWEEN #{statTimeStart} AND #{statTimeEnd}
UNION ALL
SELECT COUNT(CASE WHEN monitor_status IN ('0', '正常') THEN 1 END) AS normalCount, COUNT(CASE WHEN monitor_status NOT IN ('0', '正常') THEN 1 END) AS abnormalCount FROM share_charge_monitor WHERE deleted = 0
AND station_id = #{stationId}
AND create_time BETWEEN #{statTimeStart} AND #{statTimeEnd}
) all_devices

SELECT COALESCE(SUM(CASE WHEN process_status IN ('1', '待处理', '处理中') THEN 1 ELSE 0 END), 0) AS oilWaitHandleNum, CASE WHEN COUNT(*) = 0 THEN 0 ELSE ROUND(SUM(CASE WHEN process_status IN ('0', '3', '已完成', '已关闭') THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 2) END AS oilHandleCompleteRate FROM oil_monitor WHERE deleted = 0
AND station_id = #{stationId}
AND create_time BETWEEN #{statTimeStart} AND #{statTimeEnd}

SELECT si.name AS stationName, CASE WHEN (COALESCE(device.normalDeviceNum, 0) + COALESCE(device.abnormalDeviceNum, 0)) = 0 THEN '无数据' WHEN COALESCE(device.abnormalDeviceNum, 0) = 0 THEN '正常' WHEN COALESCE(device.abnormalDeviceNum, 0) * 1.0 / (COALESCE(device.normalDeviceNum, 0) + COALESCE(device.abnormalDeviceNum, 0)) < 0.1 THEN '良好' ELSE '告警' END AS deviceStatus, CASE WHEN COALESCE(user.onlineCount, 0) = 0 THEN '离线' ELSE '在线' END AS userOnlineStatus FROM station_info si LEFT JOIN (
SELECT station_id, SUM(CASE WHEN alarm_status IN ('0', '未告警') THEN 1 ELSE 0 END) AS normalDeviceNum, SUM(CASE WHEN alarm_status NOT IN ('0', '未告警') THEN 1 ELSE 0 END) AS abnormalDeviceNum FROM ( SELECT station_id, alarm_status FROM car_charge_monitor WHERE deleted = 0
AND create_time BETWEEN #{reqVO.statTimeStart} AND #{reqVO.statTimeEnd}
UNION ALL SELECT station_id, alarm_status FROM bike_charge_monitor WHERE deleted = 0
AND create_time BETWEEN #{reqVO.statTimeStart} AND #{reqVO.statTimeEnd}
UNION ALL SELECT station_id, alarm_status FROM share_charge_monitor WHERE deleted = 0
AND create_time BETWEEN #{reqVO.statTimeStart} AND #{reqVO.statTimeEnd}
) all_devices GROUP BY station_id ) device ON si.id = device.station_id LEFT JOIN (
SELECT iu.station_id, COUNT(*) AS onlineCount FROM inspect_user iu WHERE iu.deleted = 0 AND iu.online_status = '1' GROUP BY iu.station_id ) user ON si.id = user.station_id WHERE si.deleted = 0
AND si.id = #{reqVO.stationId}
ORDER BY si.id

select.if:
SELECT date_series.report_date AS date, COALESCE(device.updateCount, 0) AS deviceUpdateNum, COALESCE(task.avgHandleTime, 0) AS taskHandleTime, COALESCE(report.reportCount, 0) AS reportNum FROM (
SELECT DATE_ADD(#{reqVO.statTimeStart}, INTERVAL nums.num DAY) AS report_date FROM ( SELECT (a.N + b.N * 10 + c.N * 100) AS num FROM (SELECT 0 AS N UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) a CROSS JOIN (SELECT 0 AS N UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) b CROSS JOIN (SELECT 0 AS N UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) c ) nums WHERE DATE_ADD(#{reqVO.statTimeStart}, INTERVAL nums.num DAY) <= #{reqVO.statTimeEnd} ) date_series LEFT JOIN (
SELECT DATE(monitor_time) AS report_date, COUNT(*) AS updateCount FROM ( SELECT monitor_time FROM car_charge_monitor WHERE deleted = 0
AND station_id = #{reqVO.stationId}
UNION ALL SELECT monitor_time FROM bike_charge_monitor WHERE deleted = 0
AND station_id = #{reqVO.stationId}
UNION ALL SELECT monitor_time FROM share_charge_monitor WHERE deleted = 0
AND station_id = #{reqVO.stationId}
) all_monitor WHERE monitor_time BETWEEN #{reqVO.statTimeStart} AND #{reqVO.statTimeEnd} GROUP BY DATE(monitor_time) ) device ON date_series.report_date = device.report_date LEFT JOIN (
SELECT DATE(it.dispatch_time) AS report_date, CASE WHEN COUNT(*) = 0 THEN 0 ELSE AVG(TIMESTAMPDIFF(HOUR,it.dispatch_time,GREATEST(it.dispatch_time,COALESCE(it.claim_time, it.update_time)))) END AS avgHandleTime FROM inspect_task it LEFT JOIN inspect_plan ip ON it.plan_id = ip.id WHERE it.deleted = 0 AND ip.deleted = 0
AND it.station_id = #{reqVO.stationId}
AND it.dispatch_time BETWEEN #{reqVO.statTimeStart} AND #{reqVO.statTimeEnd} GROUP BY DATE(it.dispatch_time) ) task ON date_series.report_date = task.report_date LEFT JOIN (
SELECT DATE(create_time) AS report_date, COUNT(*) AS reportCount FROM oil_monitor WHERE deleted = 0
AND station_id = #{reqVO.stationId}
AND create_time BETWEEN #{reqVO.statTimeStart} AND #{reqVO.statTimeEnd} GROUP BY DATE(create_time) ) report ON date_series.report_date = report.report_date ORDER BY date_series.report_date

SELECT date_series.report_date AS date, COALESCE(device.updateCount, 0) AS deviceUpdateNum, COALESCE(task.avgHandleTime, 0) AS taskHandleTime, COALESCE(report.reportCount, 0) AS reportNum FROM ( SELECT CURDATE() - INTERVAL nums.num DAY AS report_date FROM (
SELECT (a.N + b.N * 10) AS num FROM ( SELECT 0 AS N UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9 ) a CROSS JOIN ( SELECT 0 AS N UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 ) b WHERE (a.N + b.N * 10) < 90 ) nums ) date_series LEFT JOIN ( SELECT DATE(monitor_time) AS report_date, COUNT(*) AS updateCount FROM ( SELECT monitor_time FROM car_charge_monitor WHERE deleted = 0
AND station_id = #{reqVO.stationId}
AND monitor_time >= CURDATE() - INTERVAL 90 DAY UNION ALL SELECT monitor_time FROM bike_charge_monitor WHERE deleted = 0
AND station_id = #{reqVO.stationId}
AND monitor_time >= CURDATE() - INTERVAL 90 DAY UNION ALL SELECT monitor_time FROM share_charge_monitor WHERE deleted = 0
AND station_id = #{reqVO.stationId}
AND monitor_time >= CURDATE() - INTERVAL 90 DAY ) all_monitor GROUP BY DATE(monitor_time) ) device ON date_series.report_date = device.report_date LEFT JOIN ( SELECT DATE(it.dispatch_time) AS report_date, CASE WHEN COUNT(*) = 0 THEN 0 ELSE AVG( TIMESTAMPDIFF( HOUR, it.dispatch_time, -- 修复：使用 GREATEST 函数，确保结束时间不早于开始时间，避免负时长 GREATEST( it.dispatch_time, COALESCE(it.claim_time, it.update_time) ) ) ) END AS avgHandleTime FROM inspect_task it LEFT JOIN inspect_plan ip ON it.plan_id = ip.id WHERE it.deleted = 0 AND ip.deleted = 0
AND it.station_id = #{reqVO.stationId}
AND it.dispatch_time >= CURDATE() - INTERVAL 90 DAY GROUP BY DATE(it.dispatch_time) ) task ON date_series.report_date = task.report_date LEFT JOIN ( SELECT DATE(create_time) AS report_date, COUNT(*) AS reportCount FROM oil_monitor WHERE deleted = 0
AND station_id = #{reqVO.stationId}
AND create_time >= CURDATE() - INTERVAL 90 DAY GROUP BY DATE(create_time) ) report ON date_series.report_date = report.report_date ORDER BY date_series.report_date

